contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        require(amount >= 0);

        uint256 ethBefore = address(c).balance;
        uint256 callerBalanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted == (callerBalanceBefore != 0)
            && c.balances(address(this)) == (reverted ? callerBalanceBefore : 0)
            && (reverted || address(c).balance == ethBefore)
        );
    }

    receive() external payable {}
}

