contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 amount) internal {
        vm.assume(amount >= 0);
        uint256 ethBefore = address(c).balance;
        uint256 callerBalanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { callerBalanceBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (callerBalanceBefore != 0)
            && c.balances(address(this)) == (reverted ? callerBalanceBefore : 0)
            && (reverted || address(c).balance == ethBefore));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
